// One Thread Per Document
//
// JSON Search (Handwired series) — chapter 1. Source pin: chenglou/handwired@4ea7fcb27ebe93acf49b9f29a93e162b975bad46 (MIT).
//   lab/json-search/README.md:52 (Cheng's question; 80 µs per document on the CPU executor; a round trip to the GPU
//     alone takes 0.6 ms or more; same operations, no document reads another one's values), 54-55 (written out: about
//     2 s to compile; the loop's shader compiles in 0.04 s and validates 100,000 documents in 2.2 ms), 118 and 140
//     (2.2 ms back to back; 2.1 s as generated JavaScript, extrapolated from 5,000 documents; 8.4 to 9.2 s on the
//     executor), 170 (one Apple M5 Max, one browser, headless; another GPU may differ), 189 (16 defects), 199 (89,943
//     valid, 10,057 broken; each defect 474 to 748), 203 (the written-out display shader: 13,350 statements),
//     244 and 771 (51.6 million values, 0 different)
//   src/json-search/json-step.ts:65-66 (cellsPerDocument: 512 code points, then the text's length), 158-183 (the two
//     stages: step, repeat forward; end, once)
//   src/json-search/highlighter/kinds.ts:8, 14 (capacity 512; the display kinds); tests/json-search/highlighter/
//     reference.ts:82-130, 224-227 (how a character gets its display kind; ported below for one valid document)
//   src/json-search/documents.ts:414 (documentAt(seed, index)), seed 20261013
//   `bun lab/json-search/report.ts loops`: JSON highlighter, step 37, end 17, 18,961 per document, 107 WGSL statements
//   `bun lab/json-search/report.ts documents`: the 16 defect counts (summed below and checked against 10,057)
//
// Authored by Claude Opus 5.5 (claude-opus-5-5) from the Sonnet 5.5 visual plan; captions are the fixed narration
// contract (verbatim). The wall is the real corpus: WALL_BITS marks which of the 100,000 documents of seed 20261013
// are broken and WALL_KINDS holds each broken one's defect, both encoded from `generateDocuments(100_000)` at the
// pin (document i is cell i, 400 per row). The unfolded row is document 0, a userRecord, verbatim, and its colours
// come from the reference highlighter's rules. Changes to the plan: the written-out stack uses the README's 13,350
// statements (the display shader) instead of "~12,000"; the 2.1 s lane is labelled "about · extrapolated"
// (review.md, visual note 4); the bars for 80 µs and 0.6 ms share one linear scale, the time lanes one log scale.
import { CAMERA_HOME, Camera, CanvasLayer, STAGE_H, STAGE_W, Timeline, cameraInterp, colors, ease } from '../../core';
import type { CameraState, ChannelRef, SceneState } from '../../core';

const clamp01 = (u: number): number => (u < 0 ? 0 : u > 1 ? 1 : u);
const lerp = (a: number, b: number, u: number): number => a + (b - a) * u;
const MONO = colors.font.mono;
const commas = (n: number): string => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
/** per-item progress from one group channel: item i starts `each` seconds after item i-1. */
const staggerU = (u: number, i: number, n: number, each: number, dur: number): number => {
  const total = dur + each * (n - 1);
  return clamp01((u * total - i * each) / dur);
};

// ---------------------------------------------------------------------------
// The corpus: 100,000 documents, seed 20261013 (documents.ts:414), encoded at the pin
// ---------------------------------------------------------------------------

const DOCS = 100_000;
const COLS = 400;
const ROWS = DOCS / COLS; // 250
const DEFECTS = [
  'missingQuote', 'trailingComma', 'badEscape', 'tooDeep', 'tooLong', 'missingColon', 'unquotedKey', 'truncatedText',
  'singleQuotes', 'badLiteral', 'badNumber', 'missingComma', 'mismatchedBracket', 'controlCharacter', 'comment', 'extraText',
] as const;
// bit i set ⇔ document i is broken (little-endian bits, 12,500 bytes)
const WALL_BITS = '';
// the defect index (into DEFECTS) of each broken document in order, two per byte, low nibble first
const WALL_KINDS = '';

const fromBase64 = (b64: string): Uint8Array => {
  const raw = atob(b64);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
};
/** -1 for a valid document, else its defect index */
const DEFECT_OF: Int8Array = (() => {
  const bits = fromBase64(WALL_BITS);
  const nib = fromBase64(WALL_KINDS);
  const out = new Int8Array(DOCS).fill(-1);
  let j = 0;
  for (let i = 0; i < DOCS; i++) {
    if (bits[i >> 3] & (1 << (i & 7))) {
      out[i] = (nib[j >> 1] >> ((j & 1) * 4)) & 15;
      j++;
    }
  }
  return out;
})();
const DEFECT_COUNTS = DEFECTS.map((_, k) => DEFECT_OF.reduce((n, d) => n + (d === k ? 1 : 0), 0));
const BROKEN = DEFECT_COUNTS.reduce((a, b) => a + b, 0);
const VALID = DOCS - BROKEN;
const MAX_COUNT = Math.max(...DEFECT_COUNTS);
// README.md:199 and report.ts documents — the encoding must reproduce them exactly
if (BROKEN !== 10_057 || VALID !== 89_943 || Math.min(...DEFECT_COUNTS) !== 474 || MAX_COUNT !== 748) throw new Error('corpus mismatch');
if (DEFECT_COUNTS[0] !== 616 || DEFECT_COUNTS[1] !== 608 || DEFECT_COUNTS[2] !== 616 || DEFECT_COUNTS[3] !== 622) throw new Error('defect counts');

// ---------------------------------------------------------------------------
// The highlighter's numbers (report.ts loops; json-step.ts; README)
// ---------------------------------------------------------------------------

const CAPACITY = 512; // kinds.ts:8
const CELLS_PER_DOCUMENT = CAPACITY + 1; // json-step.ts:65 — 512 code points, then the text's length
const STEP_OPS = 37;
const END_OPS = 17;
const OPS_PER_DOC = STEP_OPS * CAPACITY + END_OPS;
if (OPS_PER_DOC !== 18_961) throw new Error('18,961');
const OPS_ALL = OPS_PER_DOC * DOCS; // 1,896,100,000 — "about 1.9 billion"
const LOOP_STATEMENTS = 107;
const WRITTEN_STATEMENTS = 13_350; // README.md:203, the first stage's display shader
const COMPARED_VALUES = DOCS * (CAPACITY + 4); // 512 display kinds + the 4 summary values per document
if (COMPARED_VALUES !== 51_600_000) throw new Error('51.6 million');

// Document 0 of the corpus (a userRecord, valid), verbatim from `report.ts examples`.
const DOC0 =
  '{\n  "id": 23416,\n  "name": "Linus Müller",\n  "email": "linus.55@example.com",\n  "age": 58,\n  "address": {\n    "street": "253 Rua das Flores",\n    "city": "Muscat",\n    "zip": "18146",\n    "country": "EC"\n  },\n  "balance": -421.27,\n  "bio": "the or washed to an train"\n}';
const DOC0_CP = Array.from(DOC0);
const DOC0_LEN = DOC0_CP.length; // 269

type Kind = 'whitespace' | 'punctuation' | 'string' | 'number' | 'literal' | 'key' | 'pastEnd';
/** The reference highlighter's display kinds (reference.ts:82-130, 224-227) for a valid document without escapes. */
const DOC0_KINDS: Kind[] = (() => {
  const k: Kind[] = Array.from({ length: CAPACITY }, () => 'pastEnd');
  const strings: Array<[number, number]> = [];
  let i = 0;
  while (i < DOC0_LEN) {
    const c = DOC0_CP[i];
    if (' \t\n\r'.includes(c)) k[i++] = 'whitespace';
    else if ('{}[]:,'.includes(c)) k[i++] = 'punctuation';
    else if (c === '"') {
      const s = i;
      k[i++] = 'string';
      while (DOC0_CP[i] !== '"') k[i++] = 'string';
      k[i++] = 'string';
      strings.push([s, i]);
    } else if (c === '-' || /[0-9]/.test(c)) {
      while (i < DOC0_LEN && /[-+.eE0-9]/.test(DOC0_CP[i])) k[i++] = 'number';
    } else {
      while (i < DOC0_LEN && /[a-z]/.test(DOC0_CP[i])) k[i++] = 'literal';
    }
  }
  // a string followed by a colon is a key
  for (const [s, e] of strings) {
    let j = e;
    while (j < DOC0_LEN && k[j] === 'whitespace') j++;
    if (DOC0_CP[j] === ':') for (let p = s; p < e; p++) k[p] = 'key';
  }
  return k;
})();
const KIND_COLOR: Record<Kind, string> = {
  key: colors.SECONDARY,
  string: colors.POSITIVE,
  number: colors.WARM,
  literal: colors.TEAL,
  punctuation: '#e6edf6',
  whitespace: colors.MUTED,
  pastEnd: '#334155',
};
const KIND_LEGEND: Kind[] = ['key', 'string', 'number', 'punctuation', 'whitespace', 'pastEnd'];
const KIND_LABEL: Record<Kind, string> = {
  key: 'key', string: 'string', number: 'number', literal: 'literal', punctuation: 'punctuation', whitespace: 'whitespace', pastEnd: 'pastEnd',
};

// ---------------------------------------------------------------------------
// Layout (stage 1280×720; the caption band y ≥ 630 stays empty)
// ---------------------------------------------------------------------------

const WALL = { x: 70, y: 120, w: 600, h: 375 };
const CELL = WALL.w / COLS; // 1.5
const RES = 2; // backing pixels per stage unit
const LIT = colors.TEAL;
const BAD = colors.NEGATIVE;

// the unfolded row: 512 slots, 32 per line, then the length cell
const ROW = { x: 90, y: 150, px: 21, py: 23, w: 19, h: 21, per: 32 };
const SHRUNK = { x: 130, y: 205, s: 0.55 };
const slotRel = (i: number) => (i < CAPACITY ? { x: (i % ROW.per) * ROW.px, y: Math.floor(i / ROW.per) * ROW.py, w: ROW.w } : { x: ROW.per * ROW.px + 8, y: 15 * ROW.py, w: 60 });

// the C2 panel: one document, shared linear scale (µs → px)
const ONE = { x: 770, us: 0.5 };
// the time lanes: one log axis, 1 ms … 10 s
const LANE = { x0: 790, x1: 1210, top: 170 };
const logX = (ms: number) => LANE.x0 + ((Math.log10(ms) - 0) / 4) * (LANE.x1 - LANE.x0);
// the statement stacks
const STACK = { base: 560, loopX: 620, wideX: 860, w: 90, wideH: 300 };

// the C1/C3 inset: a patch of neighbouring documents, magnified
const INSET = { x: 760, y: 170, cell: 34, gap: 8, cols: 9, rows: 5 };

const CAM_OPEN: CameraState = { x: 640, y: 340, k: 1.08 };
const CAM_ONE: CameraState = { x: 800, y: 300, k: 1.12 };
// push in on document 0 at the wall's top-left corner
const CAM_DOC0: CameraState = { x: WALL.x + 75, y: WALL.y + 31, k: 3.2 };
const CAM_ROW: CameraState = { x: 640, y: 335, k: 1.06 };
const CAM_CODE: CameraState = { x: 690, y: 345, k: 1.05 };
const CAM_LANES: CameraState = { x: 900, y: 335, k: 1.12 };

// ---------------------------------------------------------------------------
// Timeline — twelve fixed captions, ≈149 s
// ---------------------------------------------------------------------------

const CAPTIONS = [
  'Cheng asked whether regex search or a JSON highlighter could run clearly faster on a graphics chip. The lab tests that on one hundred thousand generated JSON documents.',
  'For a single document, no. The highlighter takes eighty microseconds on the CPU executor, and a round trip to the GPU alone costs six tenths of a millisecond or more.',
  "Many documents are another story. Every document runs the same operations, and no document reads another one's values. That is a thread per document.",
  "Each document is a row of up to five hundred twelve code points, followed by the text's length. One GPU thread reads its own row and never anyone else's.",
  'Of the hundred thousand, 89,943 are valid and 10,057 are broken, spread over sixteen kinds of defect: a missing quote, a trailing comma, a bad escape, nesting too deep.',
  'The highlighter is one step of work per position. Thirty-seven operations read a code point, and seventeen more close the document, so a full row costs 18,961 operations.',
  'The step is written once, inside a loop over positions. That shader is 107 statements long, and it compiles in about four hundredths of a second.',
  'Written out position by position, the first version of this shader took about two seconds to compile. The loop turned a compile limit into a detail.',
  'Across the hundred thousand documents, that is about 1.9 billion operations in one pass, which is simple arithmetic: 18,961 times one hundred thousand.',
  'With the documents already on the GPU, validating and highlighting all hundred thousand takes 2.2 milliseconds when passes follow each other.',
  "The same program as generated JavaScript on the CPU takes about 2.1 seconds, extrapolated from 5,000 documents. On the CPU executor it takes 8.4 to 9.2 seconds. Every value from the GPU matched the CPU's.",
  'Scope: one Apple M5 Max through Metal, headless Chrome, generated documents. The lab itself says another GPU or browser may differ.',
];
/** speaking time at ~150 words per minute, plus a breath */
const speak = (text: string) => +(text.split(/\s+/).length / 2.5 + 0.8).toFixed(1);
const HOLD = 0.5;

export function buildScene() {
  const tl = new Timeline();
  const cam = tl.channel<CameraState>('cam', CAM_OPEN, cameraInterp);

  // the wall
  const wallIn = tl.channel('wallIn', 0);
  const wallOp = tl.channel('wallOp', 1);
  const litFront = tl.channel('litFront', 0);
  const litOp = tl.channel('litOp', 0);
  const badOp = tl.channel('badOp', 0);
  const kindSpot = tl.channel('kindSpot', -1);
  const kindOp = tl.channel('kindOp', 0);
  const wallLbl = tl.channel('wallLabel', 0);
  const doc0Ring = tl.channel('doc0Ring', 0);
  const patchOp = tl.channel('patchOp', 0);
  // C1 question chips, C2 one-document panel, C3 inset
  const askU = tl.channel('askU', 0);
  const oneU = tl.channel('oneU', 0);
  const oneBars = tl.channel('oneBars', 0);
  const oneVerdict = tl.channel('oneVerdict', 0);
  const insetU = tl.channel('insetU', 0);
  const insetTxt = tl.channel('insetText', 0);
  // the row (document 0)
  const rowU = tl.channel('rowU', 0);
  const rowOp = tl.channel('rowOp', 1);
  const rowLbl = tl.channel('rowLabels', 0);
  const threadU = tl.channel('threadU', 0);
  const pose = tl.channel('rowPose', 0);
  const head = tl.channel('readHead', 0);
  const headOp = tl.channel('headOp', 0);
  const stepPanel = tl.channel('stepPanel', 0);
  const endU = tl.channel('endU', 0);
  // defects legend
  const legendU = tl.channel('legendU', 0);
  // the code and the stacks
  const codeU = tl.channel('codeU', 0);
  const ringU = tl.channel('loopRing', 0);
  const loopStack = tl.channel('loopStack', 0);
  const squeeze = tl.channel('squeeze', 0);
  const wideU = tl.channel('wideU', 0);
  const wideGhost = tl.channel('wideGhost', 0);
  const codeOp = tl.channel('codeOp', 1);
  // the pass, the clocks, the scope
  const sumU = tl.channel('sumU', 0);
  const sumOp = tl.channel('sumOp', 1);
  const axisU = tl.channel('axisU', 0);
  const gpuU = tl.channel('gpuLane', 0);
  const jsU = tl.channel('jsLane', 0);
  const exU = tl.channel('execLane', 0);
  const sealU = tl.channel('sealU', 0);
  const lanesOp = tl.channel('lanesOp', 1);
  const scopeU = tl.channel('scopeU', 0);

  let t = 0.4;
  const beats: number[] = [];
  for (const text of CAPTIONS) {
    beats.push(t);
    const dur = speak(text);
    tl.caption({ at: t, dur, text });
    t = tl.hold(t + dur, HOLD);
  }
  const B = (i: number) => beats[i];

  // — C1 · the question, and a wall of 100,000 documents —
  let b = B(0);
  tl.tween(wallIn, 1, { at: b + 0.2, dur: 1.6, ease: ease.linear });
  tl.tween(cam, CAMERA_HOME, { at: b + 1.0, dur: 1.4, ease: ease.move });
  tl.tween(askU, 1, { at: b + 2.0, dur: 0.7, ease: ease.enter });
  tl.tween(wallLbl, 1, { at: b + 7.4, dur: 0.6, ease: ease.enter });

  // — C2 · one document: 80 µs on the CPU, 0.6 ms just to reach the GPU —
  b = B(1);
  tl.tween(askU, 0, { at: b, dur: 0.6, ease: ease.move });
  tl.tween(wallOp, 0.15, { at: b + 0.2, dur: 0.8, ease: ease.move });
  tl.tween(wallLbl, 0, { at: b + 0.2, dur: 0.6, ease: ease.move });
  tl.tween(doc0Ring, 1, { at: b + 0.6, dur: 0.6, ease: ease.pop });
  tl.tween(cam, CAM_ONE, { at: b + 1.6, dur: 1.3, ease: ease.move });
  tl.tween(oneU, 1, { at: b + 2.0, dur: 0.7, ease: ease.enter });
  tl.tween(oneBars, 1, { at: b + 3.6, dur: 1.2, ease: ease.draw });
  tl.tween(oneBars, 2, { at: b + 6.6, dur: 1.4, ease: ease.draw });
  tl.tween(oneVerdict, 1, { at: b + 9.2, dur: 0.6, ease: ease.enter });

  // — C3 · many documents: the same operations, no reads across, one thread each —
  b = B(2);
  tl.tween(cam, CAMERA_HOME, { at: b, dur: 1.3, ease: ease.move });
  tl.tween(oneU, 0, { at: b, dur: 0.6, ease: ease.move });
  tl.tween(doc0Ring, 0, { at: b, dur: 0.5, ease: ease.move });
  tl.tween(wallOp, 1, { at: b + 0.3, dur: 0.8, ease: ease.move });
  tl.tween(insetU, 1, { at: b + 1.0, dur: 0.7, ease: ease.enter });
  tl.set(litOp, 1, b + 1.6);
  tl.tween(litFront, 1, { at: b + 1.7, dur: 3.2, ease: ease.linear });
  tl.tween(insetTxt, 1, { at: b + 3.0, dur: 2.6, ease: ease.linear });
  tl.tween(wallLbl, 2, { at: b + 7.0, dur: 0.6, ease: ease.enter });

  // — C4 · push into document 0; it unfolds into a row of 512 cells and its length —
  b = B(3);
  tl.tween(insetU, 0, { at: b, dur: 0.6, ease: ease.move });
  tl.tween(litOp, 0, { at: b, dur: 0.8, ease: ease.move });
  tl.tween(wallLbl, 0, { at: b, dur: 0.5, ease: ease.move });
  tl.tween(cam, CAM_DOC0, { at: b + 0.2, dur: 1.5, ease: ease.move });
  tl.tween(patchOp, 1, { at: b + 0.8, dur: 0.6, ease: ease.enter });
  tl.tween(doc0Ring, 1, { at: b + 1.4, dur: 0.5, ease: ease.pop });
  tl.tween(cam, CAMERA_HOME, { at: b + 3.0, dur: 1.5, ease: ease.move });
  tl.tween(patchOp, 0, { at: b + 3.0, dur: 0.6, ease: ease.move });
  tl.tween(doc0Ring, 0, { at: b + 3.0, dur: 0.4, ease: ease.move });
  tl.tween(wallOp, 0.08, { at: b + 3.0, dur: 1.0, ease: ease.move });
  tl.tween(rowU, 1, { at: b + 3.0, dur: 2.0, ease: ease.move });
  tl.tween(rowLbl, 1, { at: b + 5.0, dur: 0.6, ease: ease.enter });
  tl.tween(threadU, 1, { at: b + 7.6, dur: 0.7, ease: ease.enter });

  // — C5 · back to the wall: 10,057 broken, sixteen defects —
  b = B(4);
  tl.tween(threadU, 0, { at: b, dur: 0.5, ease: ease.move });
  tl.tween(rowLbl, 0, { at: b, dur: 0.5, ease: ease.move });
  tl.tween(rowU, 0, { at: b + 0.1, dur: 1.3, ease: ease.move });
  tl.tween(wallOp, 1, { at: b + 0.6, dur: 0.8, ease: ease.move });
  tl.tween(badOp, 1, { at: b + 1.6, dur: 1.0, ease: ease.enter });
  tl.tween(wallLbl, 3, { at: b + 2.0, dur: 0.6, ease: ease.enter });
  tl.tween(legendU, 1, { at: b + 3.6, dur: 1.6, ease: ease.linear });
  // the four spoken kinds, as they are named (from ~8.6 s into the line)
  tl.tween(kindOp, 1, { at: b + 8.3, dur: 0.4, ease: ease.enter });
  [0, 1, 2, 3].forEach((k, i) => tl.set(kindSpot, k, b + 8.4 + i * 0.8));

  // — C6 · the step, position by position: 37 each, 17 at the end —
  b = B(5);
  tl.tween(kindOp, 0, { at: b, dur: 0.5, ease: ease.move });
  tl.tween(legendU, 0, { at: b, dur: 0.6, ease: ease.move });
  tl.tween(wallLbl, 0, { at: b, dur: 0.5, ease: ease.move });
  tl.tween(wallOp, 0.08, { at: b + 0.2, dur: 0.8, ease: ease.move });
  tl.tween(rowU, 1, { at: b + 0.2, dur: 1.6, ease: ease.move });
  tl.tween(cam, CAM_ROW, { at: b + 0.6, dur: 1.3, ease: ease.move });
  tl.tween(stepPanel, 1, { at: b + 1.8, dur: 0.6, ease: ease.enter });
  tl.tween(headOp, 1, { at: b + 2.2, dur: 0.4, ease: ease.enter });
  tl.tween(head, CAPACITY, { at: b + 2.4, dur: 5.6, ease: ease.linear });
  tl.tween(head, CAPACITY + 1, { at: b + 8.1, dur: 0.5, ease: ease.linear });
  tl.tween(endU, 1, { at: b + 8.3, dur: 0.6, ease: ease.pop });

  // — C7 · written once, inside a loop: 107 statements —
  b = B(6);
  tl.tween(headOp, 0, { at: b, dur: 0.5, ease: ease.move });
  tl.tween(stepPanel, 0, { at: b, dur: 0.6, ease: ease.move });
  tl.tween(pose, 1, { at: b + 0.1, dur: 1.3, ease: ease.move });
  tl.tween(rowOp, 0.15, { at: b + 1.0, dur: 0.8, ease: ease.move });
  tl.tween(cam, CAM_CODE, { at: b + 0.3, dur: 1.3, ease: ease.move });
  tl.tween(codeU, 1, { at: b + 1.2, dur: 0.7, ease: ease.enter });
  tl.tween(ringU, 1, { at: b + 2.6, dur: 1.2, ease: ease.draw });
  tl.tween(loopStack, 1, { at: b + 4.6, dur: 1.4, ease: ease.linear });

  // — C8 · written out position by position: 13,350 statements, about 2 s to compile —
  b = B(7);
  tl.tween(wideU, 1, { at: b + 0.6, dur: 1.6, ease: ease.draw });
  tl.tween(squeeze, 1, { at: b + 0.6, dur: 1.6, ease: ease.move });
  tl.tween(wideGhost, 1, { at: b + 6.4, dur: 0.8, ease: ease.move });

  // — C9 · pull back: the whole wall in one pass, 1.9 billion operations —
  b = B(8);
  tl.tween(codeOp, 0, { at: b, dur: 0.6, ease: ease.move });
  tl.tween(cam, CAMERA_HOME, { at: b, dur: 1.4, ease: ease.move });
  tl.tween(rowOp, 1, { at: b, dur: 0.4, ease: ease.move });
  tl.tween(rowU, 0, { at: b + 0.2, dur: 1.4, ease: ease.move });
  tl.tween(wallOp, 1, { at: b + 0.8, dur: 0.8, ease: ease.move });
  tl.tween(badOp, 0.55, { at: b + 0.8, dur: 0.8, ease: ease.move });
  tl.set(litFront, 0, b + 1.6);
  tl.set(litOp, 1, b + 1.7);
  tl.tween(litFront, 1, { at: b + 1.8, dur: 1.2, ease: ease.linear });
  tl.tween(sumU, 1, { at: b + 3.2, dur: 0.7, ease: ease.enter });

  // — C10 · 2.2 ms with the documents already on the GPU —
  b = B(9);
  tl.tween(sumOp, 0, { at: b, dur: 0.6, ease: ease.move });
  tl.tween(wallOp, 0.15, { at: b + 0.2, dur: 0.8, ease: ease.move });
  tl.tween(cam, CAM_LANES, { at: b + 0.2, dur: 1.3, ease: ease.move });
  tl.tween(axisU, 1, { at: b + 0.8, dur: 1.2, ease: ease.draw });
  tl.tween(gpuU, 1, { at: b + 3.6, dur: 0.6, ease: ease.pop });

  // — C11 · the CPU lanes, and the check —
  b = B(10);
  tl.tween(jsU, 1, { at: b + 0.6, dur: 1.4, ease: ease.draw });
  tl.tween(exU, 1, { at: b + 5.4, dur: 1.4, ease: ease.draw });
  tl.tween(sealU, 1, { at: b + 10.6, dur: 0.6, ease: ease.pop });

  // — C12 · scope —
  b = B(11);
  tl.tween(cam, CAMERA_HOME, { at: b, dur: 1.4, ease: ease.move });
  tl.tween(lanesOp, 0, { at: b, dur: 0.8, ease: ease.move });
  tl.tween(wallOp, 0.1, { at: b, dur: 0.8, ease: ease.move });
  tl.tween(scopeU, 1, { at: b + 0.8, dur: 0.7, ease: ease.enter });
  tl.hold(t, 2.0);

  return {
    tl, cam, wallIn, wallOp, litFront, litOp, badOp, kindSpot, kindOp, wallLbl, doc0Ring, patchOp,
    askU, oneU, oneBars, oneVerdict, insetU, insetTxt,
    rowU, rowOp, rowLbl, threadU, pose, head, headOp, stepPanel, endU, legendU,
    codeU, ringU, loopStack, squeeze, wideU, wideGhost, codeOp,
    sumU, sumOp, axisU, gpuU, jsU, exU, sealU, lanesOp, scopeU,
  };
}

const scene = buildScene();

// ---------------------------------------------------------------------------
// The wall's bitmaps: built once in the browser, one 2×2 dot per document (3 px pitch at 2× backing)
// ---------------------------------------------------------------------------

type WallLayers = { base: HTMLCanvasElement; lit: HTMLCanvasElement; bad: HTMLCanvasElement; kinds: HTMLCanvasElement[] };
let LAYERS: WallLayers | null = null;
/** a stable per-document shade, so the wall reads as cells rather than a flat block */
const shade = (i: number): number => {
  let h = Math.imul(i ^ 0x9e3779b9, 0x85ebca6b);
  h ^= h >>> 13;
  h = Math.imul(h, 0xc2b2ae35);
  return ((h >>> 0) % 1000) / 1000;
};
function wallLayers(): WallLayers | null {
  if (LAYERS) return LAYERS;
  if (typeof document === 'undefined') return null;
  const W = WALL.w * RES;
  const H = WALL.h * RES;
  const make = (paint: (i: number) => string | null, dot = 2): HTMLCanvasElement => {
    const c = document.createElement('canvas');
    c.width = W;
    c.height = H;
    const ctx = c.getContext('2d')!;
    for (let i = 0; i < DOCS; i++) {
      const fill = paint(i);
      if (!fill) continue;
      ctx.fillStyle = fill;
      ctx.fillRect((i % COLS) * 3, Math.floor(i / COLS) * 3, dot, dot);
    }
    return c;
  };
  LAYERS = {
    base: make((i) => `rgba(148, 163, 184, ${(0.3 + 0.2 * shade(i)).toFixed(3)})`),
    lit: make((i) => `rgba(45, 212, 191, ${(0.55 + 0.4 * shade(i)).toFixed(3)})`),
    bad: make((i) => (DEFECT_OF[i] >= 0 ? BAD : null)),
    kinds: [0, 1, 2, 3].map((k) => make((i) => (DEFECT_OF[i] === k ? colors.WARM : null), 3)),
  };
  return LAYERS;
}

function drawWall(ctx: CanvasRenderingContext2D, s: SceneState) {
  const L = wallLayers();
  if (!L) return;
  const op = s.get(scene.wallOp);
  const rows = Math.round(clamp01(s.get(scene.wallIn)) * ROWS);
  if (op <= 0.005 || rows <= 0) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0); // draw in backing pixels: 3 px per document
  const W = WALL.w * RES;
  const h = rows * 3;
  const kindOp = s.get(scene.kindOp);
  ctx.globalAlpha = op * (1 - 0.6 * kindOp);
  ctx.drawImage(L.base, 0, 0, W, h, 0, 0, W, h);
  const litOp = s.get(scene.litOp);
  const front = Math.round(clamp01(s.get(scene.litFront)) * COLS) * 3;
  if (litOp > 0.005 && front > 0) {
    ctx.globalAlpha = op * litOp;
    ctx.drawImage(L.lit, 0, 0, front, h, 0, 0, front, h);
  }
  const badOp = s.get(scene.badOp) * (1 - 0.75 * kindOp);
  if (badOp > 0.005) {
    ctx.globalAlpha = op * badOp;
    ctx.drawImage(L.bad, 0, 0, W, h, 0, 0, W, h);
  }
  const k = Math.round(s.get(scene.kindSpot));
  if (kindOp > 0.005 && k >= 0) {
    ctx.globalAlpha = op * kindOp;
    ctx.drawImage(L.kinds[k], 0, 0, W, h, 0, 0, W, h);
  }
  ctx.globalAlpha = 1;
}

// the magnified patch around document 0 (crisp SVG cells while the camera is close)
const PATCH = Array.from({ length: 28 * 46 }, (_, j) => {
  const r = Math.floor(j / 46);
  const c = j % 46;
  const i = r * COLS + c;
  return { i, x: WALL.x + c * CELL, y: WALL.y + r * CELL, bad: DEFECT_OF[i] >= 0, sh: shade(i) };
});

// the inset's documents (C3): the wall's first rows, magnified
const INSET_DOCS = Array.from({ length: INSET.cols * INSET.rows }, (_, j) => {
  const r = Math.floor(j / INSET.cols);
  const c = j % INSET.cols;
  return { i: r * COLS + c, r, c };
});

// ---------------------------------------------------------------------------
// Render
// ---------------------------------------------------------------------------

function Pill({ x, y, text, color, opacity = 1, size = 16 }: { x: number; y: number; text: string; color: string; opacity?: number; size?: number }) {
  if (opacity <= 0.005) return null;
  const w = text.length * size * 0.6 + 26;
  return (
    <g opacity={opacity}>
      <rect x={x} y={y - size} width={w} height={size * 1.9} rx={size * 0.95} fill={colors.PANEL} stroke={color} strokeWidth={1.5} />
      <text x={x + 13} y={y + size * 0.32} fontSize={size} fontFamily={MONO} fill={color}>
        {text}
      </text>
    </g>
  );
}

function Check({ x, y, s = 1, color = colors.POSITIVE }: { x: number; y: number; s?: number; color?: string }) {
  return <path d={`M ${x - 9 * s} ${y} L ${x - 3 * s} ${y + 7 * s} L ${x + 10 * s} ${y - 8 * s}`} fill="none" stroke={color} strokeWidth={3.5} strokeLinecap="round" strokeLinejoin="round" />;
}

export function Render({ s }: { s: SceneState }) {
  const v = (ch: ChannelRef<number>): number => s.get(ch);
  const cam = s.get(scene.cam);

  const wallOp = v(scene.wallOp);
  const wallIn = v(scene.wallIn);
  const wallLbl = v(scene.wallLbl);
  const litOp = v(scene.litOp);
  const front = clamp01(v(scene.litFront));
  const patchOp = v(scene.patchOp);
  const ring = v(scene.doc0Ring);

  // the row
  const rowU = v(scene.rowU);
  const rowOp = v(scene.rowOp);
  const pose = v(scene.pose);
  const bx = lerp(ROW.x, SHRUNK.x, pose);
  const by = lerp(ROW.y, SHRUNK.y, pose);
  const sc = lerp(1, SHRUNK.s, pose);
  const head = v(scene.head);
  const headOp = v(scene.headOp);
  const charOp = clamp01(1 - pose * 2.5);
  const passed = Math.min(CAPACITY, Math.floor(head));
  const ops = STEP_OPS * passed + (head >= CAPACITY + 0.999 ? END_OPS : 0);

  // C1 / C3 labels under the wall
  const lblA = clamp01(1 - Math.abs(wallLbl - 1));
  const lblB = clamp01(1 - Math.abs(wallLbl - 2));
  const lblC = clamp01(1 - Math.abs(wallLbl - 3));

  // the code panel
  const codeOp = v(scene.codeOp) * v(scene.codeU);
  const squeeze = v(scene.squeeze);
  const wideH = STACK.wideH * v(scene.wideU);
  // statements per pixel: the loop stack alone is 107 bars of 2.4 px; beside the tower both share one scale
  const unit = Math.exp(lerp(Math.log(2.4), Math.log(STACK.wideH / WRITTEN_STATEMENTS), squeeze));
  const loopH = LOOP_STATEMENTS * unit * v(scene.loopStack);

  // the lanes
  const lanesOp = v(scene.lanesOp);
  const axisU = v(scene.axisU);

  // screen-space label for document 0 while the camera is close
  const toScreen = (x: number, y: number) => ({ x: STAGE_W / 2 + cam.k * (x - cam.x), y: STAGE_H / 2 + cam.k * (y - cam.y) });
  const d0 = toScreen(WALL.x + CELL / 2, WALL.y + CELL / 2);

  return (
    <>
      <rect width={STAGE_W} height={STAGE_H} fill={colors.BG} />
      <Camera {...cam}>
        {/* ================= the wall: 100,000 documents, one cell each ================= */}
        {wallOp * wallIn > 0.005 && <CanvasLayer state={s} draw={drawWall} x={WALL.x} y={WALL.y} width={WALL.w} height={WALL.h} />}
        {litOp > 0.005 && front > 0.002 && front < 0.998 && (
          <line x1={WALL.x + front * WALL.w} y1={WALL.y - 6} x2={WALL.x + front * WALL.w} y2={WALL.y + WALL.h + 6} stroke={LIT} strokeWidth={2.5} opacity={litOp * wallOp} />
        )}
        {patchOp > 0.005 && (
          <g opacity={patchOp}>
            <rect x={WALL.x - 1} y={WALL.y - 1} width={46 * CELL + 1} height={28 * CELL + 1} fill={colors.BG} />
            {PATCH.map((p) => (
              <rect key={p.i} x={p.x} y={p.y} width={CELL * 0.72} height={CELL * 0.72} fill={p.bad ? BAD : `rgba(148, 163, 184, ${(0.3 + 0.2 * p.sh).toFixed(3)})`} />
            ))}
          </g>
        )}
        {ring > 0.005 && (
          <g opacity={clamp01(ring)}>
            <rect x={WALL.x - 0.6} y={WALL.y - 0.6} width={CELL * 0.72 + 1.2} height={CELL * 0.72 + 1.2} fill={colors.WARM} />
            <circle cx={WALL.x + 0.55} cy={WALL.y + 0.55} r={lerp(30, 9, clamp01(ring)) / (cam.k > 2 ? 3 : 1)} fill="none" stroke={colors.WARM} strokeWidth={cam.k > 2 ? 0.7 : 2} />
          </g>
        )}
        {wallIn > 0.005 && (
          <g opacity={wallIn}>
            <g opacity={lblA}>
              <text x={WALL.x} y={WALL.y + WALL.h + 32} fontSize={18} fill={colors.TEXT}>
                100,000 documents · one cell each
              </text>
              <text x={WALL.x} y={WALL.y + WALL.h + 56} fontSize={14} fontFamily={MONO} fill={colors.MUTED}>
                generated, up to 512 code points, 400 per row
              </text>
            </g>
            <g opacity={lblB}>
              <text x={WALL.x} y={WALL.y + WALL.h + 32} fontSize={18} fill={LIT}>
                every cell runs the same operations, once
              </text>
              <text x={WALL.x} y={WALL.y + WALL.h + 56} fontSize={14} fontFamily={MONO} fill={colors.MUTED}>
                no cell reads another one's values
              </text>
            </g>
            <g opacity={lblC}>
              <text x={WALL.x} y={WALL.y + WALL.h + 32} fontSize={18} fill={colors.TEXT}>
                <tspan fill={colors.MUTED}>{commas(VALID)} valid</tspan>
                <tspan> · </tspan>
                <tspan fill={BAD}>{commas(BROKEN)} broken</tspan>
              </text>
              <text x={WALL.x} y={WALL.y + WALL.h + 56} fontSize={14} fontFamily={MONO} fill={colors.MUTED}>
                the real corpus, seed 20261013: document i is cell i
              </text>
            </g>
          </g>
        )}

        {/* ================= C1 · the question ================= */}
        {v(scene.askU) > 0.005 && (
          <g opacity={v(scene.askU)}>
            <Pill x={760} y={185} text="lab/json-search" color={colors.MUTED} size={15} />
            <Pill x={760} y={260} text="JSON highlighter" color={colors.TEXT} opacity={staggerU(v(scene.askU), 0, 2, 0.3, 0.7)} size={18} />
            <Pill x={760} y={320} text="regex search" color={colors.TEXT} opacity={staggerU(v(scene.askU), 1, 2, 0.3, 0.7)} size={18} />
            <text x={762} y={398} fontSize={22} fill={colors.WARM}>
              clearly faster on a GPU?
            </text>
          </g>
        )}

        {/* ================= C2 · one document ================= */}
        {v(scene.oneU) > 0.005 && (
          <g opacity={v(scene.oneU)}>
            <rect x={ONE.x} y={120} width={44} height={44} rx={4} fill={colors.WARM} fillOpacity={0.9} />
            <text x={ONE.x + 60} y={140} fontSize={20} fill={colors.TEXT}>
              one document
            </text>
            <text x={ONE.x + 60} y={161} fontSize={14} fontFamily={MONO} fill={colors.MUTED}>
              the highlighter, alone
            </text>
            {/* shared linear scale: 0.5 px per µs */}
            <line x1={ONE.x} y1={205} x2={ONE.x} y2={395} stroke={colors.MUTED} strokeWidth={1.5} />
            <g opacity={clamp01(v(scene.oneBars) * 3)}>
              <text x={ONE.x + 12} y={232} fontSize={16} fill={colors.TEXT}>
                CPU executor
              </text>
              <rect x={ONE.x} y={244} width={80 * ONE.us * clamp01(v(scene.oneBars))} height={26} fill={colors.POSITIVE} />
              <text x={ONE.x + 80 * ONE.us + 12} y={263} fontSize={18} fontFamily={MONO} fill={colors.POSITIVE} opacity={clamp01(v(scene.oneBars) * 2 - 1)}>
                80 µs
              </text>
            </g>
            <g opacity={clamp01((v(scene.oneBars) - 1) * 3)}>
              <text x={ONE.x + 12} y={322} fontSize={16} fill={colors.TEXT}>
                GPU · the round trip alone
              </text>
              <rect x={ONE.x} y={334} width={600 * ONE.us * clamp01(v(scene.oneBars) - 1)} height={26} fill={colors.NEGATIVE} />
              <line x1={ONE.x + 600 * ONE.us} y1={347} x2={ONE.x + 600 * ONE.us + 50} y2={347} stroke={colors.NEGATIVE} strokeWidth={2.5} strokeDasharray="5 5" opacity={clamp01((v(scene.oneBars) - 1.8) * 5)} />
              <text x={ONE.x + 600 * ONE.us + 60} y={353} fontSize={18} fontFamily={MONO} fill={colors.NEGATIVE} opacity={clamp01((v(scene.oneBars) - 1.8) * 5)}>
                0.6 ms +
              </text>
            </g>
            <text x={ONE.x} y={438} fontSize={20} fill={colors.WARM} opacity={v(scene.oneVerdict)}>
              one document: no case for a GPU
            </text>
          </g>
        )}

        {/* ================= C3 · inset: neighbouring documents, a thread each, a wall between ================= */}
        {v(scene.insetU) > 0.005 && (
          <g opacity={v(scene.insetU)}>
            <text x={INSET.x} y={INSET.y - 18} fontSize={15} fontFamily={MONO} fill={colors.MUTED}>
              documents 0–8, 400–408, … magnified
            </text>
            {INSET_DOCS.map((d) => {
              const lit = litOp > 0.005 && front * COLS > d.c ? 1 : 0;
              const x = INSET.x + d.c * (INSET.cell + INSET.gap);
              const y = INSET.y + d.r * (INSET.cell + INSET.gap);
              const bad = DEFECT_OF[d.i] >= 0;
              return (
                <g key={d.i}>
                  <rect x={x} y={y} width={INSET.cell} height={INSET.cell} rx={3} fill={lit ? 'rgba(45, 212, 191, 0.25)' : colors.PANEL} stroke={bad ? BAD : lit ? LIT : colors.GRID} strokeWidth={1.5} />
                  <path d={`M ${x + 9} ${y + 7} q 8 6 0 10 q -8 4 0 10`} fill="none" stroke={lit ? LIT : colors.MUTED} strokeWidth={2} strokeLinecap="round" opacity={lit ? 1 : 0.5} />
                </g>
              );
            })}
            <g opacity={v(scene.insetTxt)}>
              {Array.from({ length: INSET.cols - 1 }, (_, c) => (
                <line key={c} x1={INSET.x + (c + 1) * (INSET.cell + INSET.gap) - INSET.gap / 2} y1={INSET.y - 4} x2={INSET.x + (c + 1) * (INSET.cell + INSET.gap) - INSET.gap / 2} y2={INSET.y + INSET.rows * (INSET.cell + INSET.gap)} stroke={colors.TEXT} strokeWidth={1.5} opacity={0.5} />
              ))}
              <text x={INSET.x} y={INSET.y + INSET.rows * (INSET.cell + INSET.gap) + 26} fontSize={18} fill={colors.TEXT}>
                no reads across the walls
              </text>
              <text x={INSET.x} y={INSET.y + INSET.rows * (INSET.cell + INSET.gap) + 56} fontSize={20} fill={LIT}>
                one GPU thread per document
              </text>
            </g>
          </g>
        )}

        {/* ================= the row: document 0, 512 code-point cells + its length ================= */}
        {rowU > 0.002 && (
          <g opacity={rowOp}>
            {v(scene.threadU) > 0.005 && (
              <rect x={bx - 10} y={by - 10} width={(ROW.per * ROW.px + 76) * sc} height={16 * ROW.py * sc + 16} rx={8} fill="none" stroke={colors.WARM} strokeWidth={2} opacity={v(scene.threadU)} />
            )}
            {Array.from({ length: CELLS_PER_DOCUMENT }, (_, i) => {
              const u = staggerU(rowU, i, CELLS_PER_DOCUMENT, 0.0016, 0.35);
              if (u <= 0) return null;
              const r = slotRel(i);
              const tx = bx + r.x * sc;
              const ty = by + r.y * sc;
              const x = lerp(WALL.x, tx, u);
              const y = lerp(WALL.y, ty, u);
              const w = lerp(CELL * 0.72, r.w * sc, u);
              const h = lerp(CELL * 0.72, ROW.h * sc, u);
              if (i === CAPACITY) {
                const lit = head >= CAPACITY + 0.2;
                return (
                  <g key={i} opacity={u}>
                    <rect x={x} y={y} width={w} height={h} rx={3} fill={lit ? 'rgba(251, 191, 36, 0.3)' : colors.PANEL} stroke={colors.WARM} strokeWidth={1.5} />
                    {charOp > 0.01 && u > 0.95 && (
                      <text x={x + w / 2} y={y + 15} textAnchor="middle" fontSize={14} fontFamily={MONO} fontWeight={700} fill={colors.WARM} opacity={charOp}>
                        {DOC0_LEN}
                      </text>
                    )}
                  </g>
                );
              }
              const kind = DOC0_KINDS[i];
              const read = i < head && headOp > 0.005;
              const c = i < DOC0_LEN ? DOC0_CP[i] : '';
              const glyph = c === '\n' ? '↵' : c === ' ' ? '·' : c;
              const faint = c === '\n' || c === ' ';
              const fill = read ? KIND_COLOR[kind] : null;
              return (
                <g key={i} opacity={u}>
                  <rect
                    x={x}
                    y={y}
                    width={w}
                    height={h}
                    rx={2}
                    fill={fill && kind !== 'pastEnd' ? fill : i < DOC0_LEN ? colors.PANEL : 'rgba(51, 65, 85, 0.25)'}
                    fillOpacity={fill && kind !== 'pastEnd' ? (faint ? 0.1 : 0.22) : 1}
                    stroke={i < DOC0_LEN ? 'rgba(148, 163, 184, 0.35)' : 'rgba(148, 163, 184, 0.14)'}
                    strokeWidth={1}
                  />
                  {glyph && charOp > 0.01 && u > 0.95 && (
                    <text x={x + w / 2} y={y + 15} textAnchor="middle" fontSize={14} fontFamily={MONO} fill={fill ?? (faint ? colors.MUTED : colors.TEXT)} opacity={charOp * (faint ? 0.45 : 1)}>
                      {glyph}
                    </text>
                  )}
                </g>
              );
            })}
            {/* the read head */}
            {headOp > 0.005 && head < CAPACITY + 0.999 && (() => {
              const i = Math.min(CAPACITY, Math.floor(head));
              const r = slotRel(i);
              return <rect x={bx + r.x * sc - 3} y={by + r.y * sc - 3} width={r.w * sc + 6} height={ROW.h * sc + 6} rx={4} fill="none" stroke="#ffffff" strokeWidth={2.5} opacity={headOp} />;
            })()}
            {/* labels */}
            <g opacity={v(scene.rowLbl) * charOp}>
              <text x={bx} y={by - 18} fontSize={16} fill={colors.TEXT}>
                document 0 · a userRecord · {DOC0_LEN} code points
              </text>
              <text x={bx} y={by + 16 * ROW.py + 22} fontSize={15} fontFamily={MONO} fill={colors.MUTED}>
                512 code-point cells, 32 per line · then the length
              </text>
              <text x={bx + slotRel(CAPACITY).x - 30} y={by + 15 * ROW.py - 12} fontSize={14} fontFamily={MONO} fill={colors.WARM}>
                length
              </text>
              <text x={bx + 470} y={by + 16 * ROW.py + 22} fontSize={15} fontFamily={MONO} fill={colors.WARM}>
                cellsPerDocument = {CELLS_PER_DOCUMENT}
              </text>
            </g>
            {v(scene.threadU) > 0.005 && (
              <g opacity={v(scene.threadU) * charOp}>
                <path d={`M ${bx + 760} ${by + 20} q 14 10 0 20 q -14 10 0 20 q 14 10 0 20`} fill="none" stroke={colors.WARM} strokeWidth={3} strokeLinecap="round" />
                <text x={bx + 790} y={by + 40} fontSize={18} fill={colors.WARM}>
                  thread 0
                </text>
                <text x={bx + 790} y={by + 64} fontSize={15} fill={colors.TEXT}>
                  reads this row
                </text>
                <text x={bx + 790} y={by + 86} fontSize={15} fill={colors.TEXT}>
                  and no other
                </text>
              </g>
            )}
          </g>
        )}

        {/* ================= C6 · the step panel ================= */}
        {v(scene.stepPanel) > 0.005 && (
          <g opacity={v(scene.stepPanel)}>
            <text x={900} y={170} fontSize={15} fontFamily={MONO} fill={colors.MUTED}>
              step · per position
            </text>
            <text x={900} y={200} fontSize={22} fontFamily={MONO} fill={colors.TEXT}>
              {STEP_OPS} operations
            </text>
            <text x={900} y={244} fontSize={15} fontFamily={MONO} fill={colors.MUTED}>
              position
            </text>
            <text x={900} y={272} fontSize={22} fontFamily={MONO} fill={colors.TEXT}>
              {Math.min(CAPACITY, passed)} / {CAPACITY}
            </text>
            <text x={900} y={316} fontSize={15} fontFamily={MONO} fill={colors.MUTED} opacity={v(scene.endU)}>
              end · once
            </text>
            <text x={900} y={344} fontSize={22} fontFamily={MONO} fill={colors.WARM} opacity={v(scene.endU)}>
              + {END_OPS}
            </text>
            <line x1={900} y1={364} x2={1160} y2={364} stroke={colors.GRID} strokeWidth={1.5} />
            <text x={900} y={398} fontSize={28} fontFamily={MONO} fontWeight={700} fill={head >= CAPACITY + 0.999 ? colors.WARM : colors.TEXT}>
              {commas(ops)}
            </text>
            <text x={900} y={422} fontSize={15} fill={colors.MUTED}>
              operations per document
            </text>
            {KIND_LEGEND.map((k, j) => (
              <g key={k} transform={`translate(${900 + (j % 2) * 140}, ${466 + Math.floor(j / 2) * 26})`}>
                <rect x={0} y={-12} width={14} height={14} rx={2} fill={KIND_COLOR[k]} fillOpacity={k === 'pastEnd' ? 1 : 0.85} />
                <text x={22} y={0} fontSize={14} fontFamily={MONO} fill={colors.MUTED}>
                  {KIND_LABEL[k]}
                </text>
              </g>
            ))}
          </g>
        )}

        {/* ================= C5 · sixteen defects ================= */}
        {v(scene.legendU) > 0.005 && (
          <g opacity={clamp01(v(scene.legendU) * 4)}>
            <text x={735} y={128} fontSize={18} fill={colors.TEXT}>
              16 kinds of defect
            </text>
            {DEFECTS.map((name, k) => {
              const u = staggerU(v(scene.legendU), k, 16, 0.05, 0.3);
              const spot = v(scene.kindOp) > 0.5 && v(scene.kindSpot) >= k - 0.01 && k < 4;
              const now = spot && Math.round(v(scene.kindSpot)) === k;
              const y = 160 + k * 23;
              return (
                <g key={name} opacity={u * (v(scene.kindOp) > 0.5 && !spot ? 0.45 : 1)}>
                  <text x={740} y={y} fontSize={14} fontFamily={MONO} fill={now ? colors.WARM : spot ? colors.TEXT : colors.MUTED}>
                    {name}
                  </text>
                  <text x={968} y={y} fontSize={14} fontFamily={MONO} textAnchor="end" fill={now ? colors.WARM : colors.TEXT}>
                    {DEFECT_COUNTS[k]}
                  </text>
                  <rect x={980} y={y - 11} width={(DEFECT_COUNTS[k] / MAX_COUNT) * 220 * u} height={12} rx={2} fill={now ? colors.WARM : BAD} opacity={now ? 1 : 0.7} />
                </g>
              );
            })}
          </g>
        )}

        {/* ================= C7 / C8 · the loop, and the stack it replaced ================= */}
        {codeOp > 0.005 && (
          <g opacity={codeOp}>
            <rect x={540} y={112} width={480} height={88} rx={6} fill={colors.PANEL} fillOpacity={0.95} stroke={colors.GRID} />
            <rect x={540} y={112} width={4} height={88} rx={2} fill={colors.WARM} />
            <text x={556} y={136} fontSize={14} fontFamily={MONO} fill={colors.MUTED}>
              {'// json-step.ts — the work of one position'}
            </text>
            <text x={556} y={160} fontSize={14} fontFamily={MONO} fill={colors.TEXT}>
              {"createStage({name: 'step', repeat: 'forward', …})"}
            </text>
            <text x={556} y={184} fontSize={14} fontFamily={MONO} fill={colors.TEXT}>
              {"createStage({name: 'end', repeat: 'once', …})"}
            </text>
            {/* the for-loop ring around the step */}
            {v(scene.ringU) > 0.005 && (() => {
              const cx = 1085;
              const cy = 155;
              const r = 34;
              const a0 = -Math.PI * 0.35;
              const span = Math.PI * 1.7 * clamp01(v(scene.ringU));
              const pts = Array.from({ length: 41 }, (_, k) => {
                const a = a0 + (span * k) / 40;
                return [cx + r * Math.cos(a), cy + r * Math.sin(a)];
              });
              const [tx, ty] = pts[40];
              const ang = a0 + span + Math.PI / 2;
              return (
                <g>
                  <line x1={1022} y1={155} x2={cx - r} y2={155} stroke={colors.WARM} strokeWidth={1.5} strokeDasharray="3 4" opacity={clamp01(v(scene.ringU) * 3)} />
                  <polyline points={pts.map((p) => p.join(',')).join(' ')} fill="none" stroke={colors.WARM} strokeWidth={3} strokeLinecap="round" />
                  <polygon points={`${tx + 9 * Math.cos(ang)},${ty + 9 * Math.sin(ang)} ${tx + 7 * Math.cos(ang + 2.3)},${ty + 7 * Math.sin(ang + 2.3)} ${tx + 7 * Math.cos(ang - 2.3)},${ty + 7 * Math.sin(ang - 2.3)}`} fill={colors.WARM} />
                  <text x={cx} y={cy + 6} textAnchor="middle" fontSize={17} fontFamily={MONO} fontWeight={700} fill={colors.WARM} opacity={clamp01(v(scene.ringU) * 2 - 0.6)}>
                    for
                  </text>
                  <text x={cx} y={cy + r + 26} textAnchor="middle" fontSize={14} fontFamily={MONO} fill={colors.MUTED} opacity={clamp01(v(scene.ringU) * 2 - 1)}>
                    positions 0…511
                  </text>
                </g>
              );
            })()}
            {/* the loop's statements: 107 bars, squeezed onto the tower's scale in C8 */}
            {v(scene.loopStack) > 0.005 && (
              <g>
                {unit >= 1.4 ? (
                  Array.from({ length: Math.round(LOOP_STATEMENTS * v(scene.loopStack)) }, (_, k) => (
                    <rect key={k} x={STACK.loopX} y={STACK.base - (k + 1) * unit} width={STACK.w} height={unit * 0.62} fill={colors.WARM} />
                  ))
                ) : (
                  <rect x={STACK.loopX} y={STACK.base - Math.max(2, loopH)} width={STACK.w} height={Math.max(2, loopH)} fill={colors.WARM} />
                )}
                <text x={STACK.loopX + STACK.w / 2} y={STACK.base - Math.max(2, loopH) - 34} textAnchor="middle" fontSize={20} fontFamily={MONO} fontWeight={700} fill={colors.WARM}>
                  {LOOP_STATEMENTS}
                </text>
                <text x={STACK.loopX + STACK.w / 2} y={STACK.base - Math.max(2, loopH) - 14} textAnchor="middle" fontSize={14} fill={colors.TEXT}>
                  WGSL statements
                </text>
                <text x={STACK.loopX + STACK.w / 2} y={STACK.base + 26} textAnchor="middle" fontSize={15} fontFamily={MONO} fill={colors.WARM}>
                  compiles in 0.04 s
                </text>
              </g>
            )}
            {wideH > 0.5 && (
              <g opacity={lerp(1, 0.3, v(scene.wideGhost))}>
                {Array.from({ length: Math.floor(wideH / 2.25) }, (_, k) => (
                  <rect key={k} x={STACK.wideX} y={STACK.base - (k + 1) * 2.25} width={STACK.w} height={1.4} fill={colors.MUTED} />
                ))}
                <text x={STACK.wideX + STACK.w + 18} y={STACK.base - wideH + 16} fontSize={20} fontFamily={MONO} fontWeight={700} fill={colors.TEXT}>
                  {commas(WRITTEN_STATEMENTS)}
                </text>
                <text x={STACK.wideX + STACK.w + 18} y={STACK.base - wideH + 40} fontSize={15} fill={colors.TEXT}>
                  statements, written out
                </text>
                <text x={STACK.wideX + STACK.w + 18} y={STACK.base - wideH + 62} fontSize={15} fill={colors.TEXT}>
                  position by position
                </text>
                <text x={STACK.wideX + STACK.w / 2} y={STACK.base + 26} textAnchor="middle" fontSize={15} fontFamily={MONO} fill={colors.MUTED}>
                  about 2 s to compile
                </text>
              </g>
            )}
            <line x1={STACK.loopX - 20} y1={STACK.base} x2={STACK.wideX + STACK.w + 20} y2={STACK.base} stroke={colors.MUTED} strokeWidth={1.5} opacity={v(scene.loopStack)} />
          </g>
        )}

        {/* ================= C9 · one pass ================= */}
        {v(scene.sumU) * v(scene.sumOp) > 0.005 && (
          <g opacity={v(scene.sumU) * v(scene.sumOp)}>
            <text x={725} y={210} fontSize={16} fill={colors.MUTED}>
              operations per document × documents
            </text>
            <text x={725} y={258} fontSize={32} fontFamily={MONO} fill={colors.TEXT}>
              {commas(OPS_PER_DOC)} × {commas(DOCS)}
            </text>
            <text x={725} y={312} fontSize={32} fontFamily={MONO} fill={LIT}>
              = {commas(OPS_ALL)}
            </text>
            <text x={727} y={370} fontSize={24} fill={LIT}>
              ≈ 1.9 billion operations
            </text>
            <text x={727} y={400} fontSize={18} fill={colors.TEXT}>
              in one pass over the wall
            </text>
          </g>
        )}

        {/* ================= C10 / C11 · the clocks, one log axis ================= */}
        {axisU > 0.005 && (
          <g opacity={lanesOp}>
            <text x={LANE.x0} y={LANE.top - 30} fontSize={16} fill={colors.MUTED} opacity={axisU}>
              validate and highlight all 100,000
            </text>
            <line x1={LANE.x0} y1={470} x2={lerp(LANE.x0, LANE.x1, axisU)} y2={470} stroke={colors.MUTED} strokeWidth={1.5} />
            {[1, 10, 100, 1000, 10000].map((ms, k) => (
              <g key={ms} opacity={staggerU(axisU, k, 5, 0.1, 0.5)}>
                <line x1={logX(ms)} y1={LANE.top - 10} x2={logX(ms)} y2={470} stroke={colors.GRID} strokeWidth={1} />
                <text x={logX(ms)} y={492} textAnchor="middle" fontSize={13} fontFamily={MONO} fill={colors.MUTED}>
                  {ms < 1000 ? `${ms} ms` : `${ms / 1000} s`}
                </text>
              </g>
            ))}
            {/* GPU */}
            <g opacity={clamp01(v(scene.gpuU) * 2)}>
              <text x={LANE.x0} y={LANE.top + 14} fontSize={16} fill={colors.TEXT}>
                GPU · documents already there, back to back
              </text>
              <rect x={LANE.x0} y={LANE.top + 26} width={(logX(2.2) - LANE.x0) * v(scene.gpuU)} height={28} fill={LIT} />
              <g transform={`translate(${logX(2.2) + 30}, ${LANE.top + 40})`} opacity={v(scene.gpuU)}>
                <circle r={13} fill="none" stroke={LIT} strokeWidth={2.5} />
                <line x1={0} y1={-17} x2={0} y2={-13} stroke={LIT} strokeWidth={3} />
                <line x1={0} y1={0} x2={6} y2={-7} stroke={LIT} strokeWidth={2.5} strokeLinecap="round" />
              </g>
              <text x={logX(2.2) + 54} y={LANE.top + 48} fontSize={24} fontFamily={MONO} fontWeight={700} fill={LIT}>
                2.2 ms
              </text>
            </g>
            {/* generated JavaScript */}
            <g opacity={clamp01(v(scene.jsU) * 3)}>
              <text x={LANE.x0} y={LANE.top + 110} fontSize={16} fill={colors.TEXT}>
                CPU · generated JavaScript
              </text>
              <rect x={LANE.x0} y={LANE.top + 122} width={(logX(2100) - LANE.x0) * v(scene.jsU)} height={28} fill={colors.SECONDARY} />
              <text x={LANE.x0} y={LANE.top + 172} fontSize={15} fontFamily={MONO} fill={colors.SECONDARY} opacity={clamp01(v(scene.jsU) * 2 - 1)}>
                about 2.1 s · extrapolated from 5,000
              </text>
            </g>
            {/* the executor */}
            <g opacity={clamp01(v(scene.exU) * 3)}>
              <text x={LANE.x0} y={LANE.top + 214} fontSize={16} fill={colors.TEXT}>
                CPU executor · every position written out
              </text>
              <rect x={LANE.x0} y={LANE.top + 226} width={(logX(9200) - LANE.x0) * v(scene.exU)} height={28} fill={colors.WARM} fillOpacity={0.8} />
              <rect x={logX(8400)} y={LANE.top + 222} width={logX(9200) - logX(8400)} height={36} fill="none" stroke="#ffffff" strokeWidth={1.5} opacity={clamp01(v(scene.exU) * 2 - 1)} />
              <text x={LANE.x1} y={LANE.top + 276} textAnchor="end" fontSize={15} fontFamily={MONO} fill={colors.WARM} opacity={clamp01(v(scene.exU) * 2 - 1)}>
                8.4–9.2 s
              </text>
            </g>
            {/* the check */}
            {v(scene.sealU) > 0.005 && (
              <g opacity={clamp01(v(scene.sealU))}>
                <rect x={LANE.x0} y={516} width={400} height={44} rx={22} fill={colors.PANEL} stroke={colors.POSITIVE} strokeWidth={2} />
                <Check x={LANE.x0 + 28} y={538} s={lerp(0.4, 1, clamp01(v(scene.sealU)))} />
                <text x={LANE.x0 + 50} y={544} fontSize={17} fontFamily={MONO} fill={colors.TEXT}>
                  51.6 million values · 0 different
                </text>
              </g>
            )}
          </g>
        )}

        {/* ================= C12 · scope ================= */}
        {v(scene.scopeU) > 0.005 && (
          <g opacity={v(scene.scopeU)}>
            <rect x={300} y={215} width={680} height={210} rx={16} fill={colors.PANEL} stroke={colors.GRID} strokeWidth={1.5} />
            <text x={640} y={272} textAnchor="middle" fontSize={26} fill={colors.TEXT}>
              Apple M5 Max · Metal · headless Chrome 155
            </text>
            <text x={640} y={318} textAnchor="middle" fontSize={19} fill={colors.TEXT}>
              100,000 generated documents, up to 512 code points
            </text>
            <text x={640} y={372} textAnchor="middle" fontSize={18} fill={colors.WARM}>
              another GPU or browser may differ
            </text>
          </g>
        )}
      </Camera>

      {/* screen-space: document 0's name while the camera is close */}
      {patchOp > 0.05 && (
        <g opacity={patchOp}>
          <line x1={d0.x - 8} y1={d0.y - 8} x2={d0.x - 48} y2={d0.y - 40} stroke={colors.WARM} strokeWidth={2} />
          <text x={d0.x - 56} y={d0.y - 66} textAnchor="end" fontSize={18} fill={colors.WARM}>
            document 0
          </text>
          <text x={d0.x - 56} y={d0.y - 44} textAnchor="end" fontSize={14} fontFamily={MONO} fill={colors.MUTED}>
            one cell = one document
          </text>
        </g>
      )}

      {/* ================= screen-space header ================= */}
      <rect x={40} y={18} width={252} height={24} rx={6} fill={colors.PANEL} stroke={colors.GRID} />
      <text x={52} y={35} fontSize={15} fill={colors.MUTED}>
        1 · One Thread Per Document
      </text>
    </>
  );
}

export const vizScene = () => scene;
